1	codeunit 70100 "CGR Fleet Mgt"
2	{
3	    procedure IsAvailable(VehicleNo: Code[20]): Boolean
4	    var
5	        Vehicle: Record "CGR Vehicle";
6	        Result: Boolean;
7	        IsHandled: Boolean;
8	    begin
9	        OnBeforeIsAvailable(VehicleNo, Result, IsHandled);
10	        if IsHandled then
11	            exit(Result);
12	        if not Vehicle.Get(VehicleNo) then
13	            exit(false);
14	        exit(not Vehicle."Checked Out" and not Vehicle.Blocked);
15	    end;
16	
17	    procedure NextServiceKm(VehicleNo: Code[20]): Integer
18	    var
19	        Vehicle: Record "CGR Vehicle";
20	        Strategy: Interface "CGR Maintenance Strategy";
21	    begin
22	        Vehicle.Get(VehicleNo);
23	        Strategy := Vehicle.Strategy;
24	        exit(Strategy.NextServiceKm(Vehicle."Last Service Km"));
25	    end;
26	
27	    [IntegrationEvent(false, false)]
28	    local procedure OnBeforeIsAvailable(VehicleNo: Code[20]; var Result: Boolean; var IsHandled: Boolean)
29	    begin
30	    end;
31	
32	    [EventSubscriber(ObjectType::Codeunit, Codeunit::"CGR Core Events", 'OnAfterVehicleCheckedOut', '', false, false)]
33	    local procedure MarkCheckedOut(VehicleNo: Code[20])
34	    var
35	        Vehicle: Record "CGR Vehicle";
36	    begin
37	        if not Vehicle.Get(VehicleNo) then
38	            exit;
39	        Vehicle."Checked Out" := true;
40	        Vehicle.Modify();
41	    end;
42	}
