1	codeunit 70200 "CGR Rental Mgt"
2	{
3	    var
4	        NotAvailableErr: Label 'Vehicle %1 is not available.', Comment = '%1 = vehicle number';
5	        WrongStatusErr: Label 'Rental contract %1 must have status %2.', Comment = '%1 = contract number, %2 = status';
6	        ReturnKmErr: Label 'Return km %1 is below the start km %2.', Comment = '%1 = return km, %2 = start km';
7	
8	    procedure CreateContract(VehicleNo: Code[20]; CustomerName: Text[100]; StartDate: Date; EndDate: Date): Code[20]
9	    var
10	        Contract: Record "CGR Rental Contract";
11	        Setup: Record "CGR Setup";
12	    begin
13	        Contract.Init();
14	        Contract."No." := Setup.NextContractNo();
15	        Contract."Vehicle No." := VehicleNo;
16	        Contract."Customer Name" := CustomerName;
17	        Contract."Start Date" := StartDate;
18	        Contract."End Date" := EndDate;
19	        Contract.Status := Contract.Status::Open;
20	        Contract.Insert(true);
21	        exit(Contract."No.");
22	    end;
23	
24	    procedure CheckOut(ContractNo: Code[20])
25	    var
26	        Contract: Record "CGR Rental Contract";
27	        Vehicle: Record "CGR Vehicle";
28	        FleetMgt: Codeunit "CGR Fleet Mgt";
29	        CoreEvents: Codeunit "CGR Core Events";
30	    begin
31	        Contract.Get(ContractNo);
32	        if Contract.Status <> Contract.Status::Open then
33	            Error(WrongStatusErr, ContractNo, Contract.Status::Open);
34	        if not FleetMgt.IsAvailable(Contract."Vehicle No.") then
35	            Error(NotAvailableErr, Contract."Vehicle No.");
36	        Vehicle.Get(Contract."Vehicle No.");
37	        Contract."Start Km" := Vehicle.Mileage;
38	        Contract.Status := Contract.Status::"Checked Out";
39	        Contract.Modify(true);
40	        CoreEvents.RaiseVehicleCheckedOut(Contract."Vehicle No.");
41	    end;
42	
43	    procedure SwapVehicle(ContractNo: Code[20]; NewVehicleNo: Code[20])
44	    var
45	        Contract: Record "CGR Rental Contract";
46	        OldVehicle: Record "CGR Vehicle";
47	        NewVehicle: Record "CGR Vehicle";
48	    begin
49	        Contract.Get(ContractNo);
50	        if Contract.Status <> Contract.Status::"Checked Out" then
51	            Error(WrongStatusErr, ContractNo, Contract.Status::"Checked Out");
52	        NewVehicle.Get(NewVehicleNo);
53	        if NewVehicle."Checked Out" or NewVehicle.Blocked then
54	            Error(NotAvailableErr, NewVehicleNo);
55	        if OldVehicle.Get(Contract."Vehicle No.") then begin
56	            OldVehicle."Checked Out" := false;
57	            OldVehicle.Modify(true);
58	        end;
59	        NewVehicle."Checked Out" := true;
60	        NewVehicle.Modify(true);
61	        Contract."Vehicle No." := NewVehicleNo;
62	        Contract."Start Km" := NewVehicle.Mileage;
63	        Contract.Modify(true);
64	    end;
65	
66	    procedure Return(ContractNo: Code[20]; ReturnKm: Integer; DamageDescription: Text[100])
67	    var
68	        Contract: Record "CGR Rental Contract";
69	        CoreEvents: Codeunit "CGR Core Events";
70	    begin
71	        Contract.Get(ContractNo);
72	        if Contract.Status <> Contract.Status::"Checked Out" then
73	            Error(WrongStatusErr, ContractNo, Contract.Status::"Checked Out");
74	        if ReturnKm < Contract."Start Km" then
75	            Error(ReturnKmErr, Format(ReturnKm, 0, 9), Format(Contract."Start Km", 0, 9));
76	        Contract."Return Km" := ReturnKm;
77	        Contract."Damage Description" := DamageDescription;
78	        Contract.Status := Contract.Status::Returned;
79	        Contract.Modify(true);
80	        CoreEvents.RaiseVehicleReturned(Contract."Vehicle No.", ReturnKm, DamageDescription);
81	    end;
82	
83	    procedure Post(ContractNo: Code[20])
84	    var
85	        Contract: Record "CGR Rental Contract";
86	    begin
87	        Contract.Get(ContractNo);
88	        Codeunit.Run(Codeunit::"CGR Rental-Post", Contract);
89	    end;
90	}
