1	codeunit 70102 "CGR Damage Mgt"
2	{
3	    procedure RegisterDamage(VehicleNo: Code[20]; Description: Text[100]): Integer
4	    var
5	        DamageEntry: Record "CGR Damage Entry";
6	    begin
7	        DamageEntry.Init();
8	        DamageEntry."Vehicle No." := VehicleNo;
9	        DamageEntry.Description := Description;
10	        DamageEntry."Reported On" := WorkDate();
11	        DamageEntry.Insert(true);
12	        OnAfterDamageRegistered(DamageEntry);
13	        exit(DamageEntry."Entry No.");
14	    end;
15	
16	    procedure RepairDamage(EntryNo: Integer)
17	    var
18	        DamageEntry: Record "CGR Damage Entry";
19	        OpenDamage: Record "CGR Damage Entry";
20	        Vehicle: Record "CGR Vehicle";
21	    begin
22	        DamageEntry.Get(EntryNo);
23	        DamageEntry.Repaired := true;
24	        DamageEntry.Modify(true);
25	        OpenDamage.SetRange("Vehicle No.", DamageEntry."Vehicle No.");
26	        OpenDamage.SetRange(Repaired, false);
27	        if Vehicle.Get(DamageEntry."Vehicle No.") then begin
28	            Vehicle."Open Damages" := OpenDamage.Count();
29	            Vehicle.Blocked := Vehicle."Open Damages" > 0;
30	            Vehicle.Modify(true);
31	        end;
32	    end;
33	
34	    [IntegrationEvent(false, false)]
35	    local procedure OnAfterDamageRegistered(var DamageEntry: Record "CGR Damage Entry")
36	    begin
37	    end;
38	}
