1	codeunit 70103 "CGR Fleet Return Handler"
2	{
3	    [EventSubscriber(ObjectType::Codeunit, Codeunit::"CGR Core Events", 'OnAfterVehicleReturned', '', false, false)]
4	    local procedure HandleVehicleReturned(VehicleNo: Code[20]; ReturnKm: Integer; DamageDescription: Text[100])
5	    var
6	        Vehicle: Record "CGR Vehicle";
7	        DamageMgt: Codeunit "CGR Damage Mgt";
8	    begin
9	        if not Vehicle.Get(VehicleNo) then
10	            exit;
11	        Vehicle."Checked Out" := false;
12	        Vehicle.Mileage := ReturnKm;
13	        Vehicle.Modify(true);
14	        if DamageDescription <> '' then
15	            DamageMgt.RegisterDamage(VehicleNo, DamageDescription);
16	    end;
17	}
