1	codeunit 80020 "CGR Fleet Tests"
2	{
3	    Subtype = Test;
4	    TestPermissions = Disabled;
5	
6	    var
7	        Assert: Codeunit "Library Assert";
8	        Lib: Codeunit "CGR Test Library";
9	
10	    [Test]
11	    procedure HeavyDutyStrategyFromFleetExtension()
12	    var
13	        FleetMgt: Codeunit "CGR Fleet Mgt";
14	    begin
15	        Lib.CreateVehicle('T-FLT-001', 1000, Enum::"CGR Maintenance Strategy"::"Heavy Duty");
16	        Lib.SetLastServiceKm('T-FLT-001', 1000);
17	        Assert.AreEqual(6000, FleetMgt.NextServiceKm('T-FLT-001'), 'Heavy Duty adds 5000 km');
18	    end;
19	
20	    [Test]
21	    procedure DamageBlocksVehicle()
22	    var
23	        Vehicle: Record "CGR Vehicle";
24	        DamageMgt: Codeunit "CGR Damage Mgt";
25	        FleetMgt: Codeunit "CGR Fleet Mgt";
26	    begin
27	        Lib.CreateVehicle('T-FLT-002', 1000, Enum::"CGR Maintenance Strategy"::Default);
28	        DamageMgt.RegisterDamage('T-FLT-002', 'Dent');
29	        Vehicle.Get('T-FLT-002');
30	        Assert.IsTrue(Vehicle.Blocked, 'Registered damage blocks the vehicle');
31	        Assert.AreEqual(1, Vehicle."Open Damages", 'One open damage');
32	        Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-002'), 'Blocked vehicle is not available');
33	    end;
34	
35	    [Test]
36	    procedure RepairLastDamageUnblocks()
37	    var
38	        Vehicle: Record "CGR Vehicle";
39	        DamageMgt: Codeunit "CGR Damage Mgt";
40	        FleetMgt: Codeunit "CGR Fleet Mgt";
41	        FirstEntryNo: Integer;
42	        SecondEntryNo: Integer;
43	    begin
44	        Lib.CreateVehicle('T-FLT-003', 1000, Enum::"CGR Maintenance Strategy"::Default);
45	        FirstEntryNo := DamageMgt.RegisterDamage('T-FLT-003', 'Dent');
46	        SecondEntryNo := DamageMgt.RegisterDamage('T-FLT-003', 'Scratch');
47	        Vehicle.Get('T-FLT-003');
48	        Assert.AreEqual(2, Vehicle."Open Damages", 'Two open damages');
49	
50	        DamageMgt.RepairDamage(FirstEntryNo);
51	        Vehicle.Get('T-FLT-003');
52	        Assert.AreEqual(1, Vehicle."Open Damages", 'One open damage after the first repair');
53	        Assert.IsTrue(Vehicle.Blocked, 'Still blocked while a damage is open');
54	
55	        DamageMgt.RepairDamage(SecondEntryNo);
56	        Vehicle.Get('T-FLT-003');
57	        Assert.AreEqual(0, Vehicle."Open Damages", 'No open damage after the last repair');
58	        Assert.IsFalse(Vehicle.Blocked, 'Unblocked after the last repair');
59	        Assert.IsTrue(FleetMgt.IsAvailable('T-FLT-003'), 'Repaired vehicle is available');
60	    end;
61	}
