      end;

      [IntegrationEvent(false, false)]
      local procedure OnAfterVehicleCheckedOut(VehicleNo: Code[20])
      begin
      end;

      [IntegrationEvent(false, false)]
      local procedure OnAfterVehicleReturned(VehicleNo: Code[20]; ReturnKm: Integer; DamageDescription: Text[100])
      begin
      end;
  }
  ```

