[Test]
procedure IsAvailableFalseWhenDueForService()
var
    FleetMgt: Codeunit "CGR Fleet Mgt";
begin
    // [GIVEN] A vehicle that is not checked out, not blocked, and whose mileage has reached its next service km
    Lib.CreateVehicle('T-FLT-004', 15000, Enum::"CGR Maintenance Strategy"::Default);

    // [WHEN] Checking availability
    // [THEN] The vehicle is reported as not available because it is due for service
    Assert.IsTrue(FleetMgt.IsDueForService('T-FLT-004'), 'Mileage equal to next service km is due for service');
    Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-004'), 'A vehicle due for service is not available');
end;

[Test]
procedure IsAvailableTrueWhenNotDueForService()
var
    FleetMgt: Codeunit "CGR Fleet Mgt";
begin
    // [GIVEN] A vehicle that is not checked out, not blocked, and well below its next service km
    Lib.CreateVehicle('T-FLT-005', 1000, Enum::"CGR Maintenance Strategy"::Default);

    // [WHEN] Checking availability
    // [THEN] The vehicle is available, as before this feature
    Assert.IsFalse(FleetMgt.IsDueForService('T-FLT-005'), 'Mileage well below next service km is not due for service');
    Assert.IsTrue(FleetMgt.IsAvailable('T-FLT-005'), 'A vehicle not due for service and not checked out/blocked is available');
end;

[Test]
procedure DueForServiceCannotBeOverriddenByExtension()
var
    FleetMgt: Codeunit "CGR Fleet Mgt";
begin
    // [GIVEN] A vehicle due for service, and an extension that unconditionally overrides availability to true
    Lib.CreateVehicle('T-FLT-006', 15000, Enum::"CGR Maintenance Strategy"::Default);
    ForceAvailableOverride := true;

    // [WHEN] Checking availability
    // [THEN] The vehicle is still reported as not available: the safety rule cannot be overridden
    Assert.IsFalse(FleetMgt.IsAvailable('T-FLT-006'), 'An extension cannot make a vehicle due for service available');
    ForceAvailableOverride := false;
end;

[Test]
procedure NotDueForServiceOverrideStillWorks()
var
    Vehicle: Record "CGR Vehicle";
    FleetMgt: Codeunit "CGR Fleet Mgt";
begin
    // [GIVEN] A vehicle not due for service but blocked (which would normally make it unavailable),
    // and an extension that unconditionally overrides availability to true
    Lib.CreateVehicle('T-FLT-007', 1000, Enum::"CGR Maintenance Strategy"::Default);
    Vehicle.Get('T-FLT-007');
    Vehicle.Blocked := true;
    Vehicle.Modify();
    ForceAvailableOverride := true;

    // [WHEN] Checking availability
    // [THEN] The extension's override still applies, because the vehicle is not due for service
    Assert.IsTrue(FleetMgt.IsAvailable('T-FLT-007'), 'An extension can still override availability for a vehicle not due for service');
    ForceAvailableOverride := false;
end;

